async function renderPromos(){const cloud=Boolean(window.beadSupabase);const read=()=>{try{return JSON.parse(localStorage.getItem('beadDifferentPromos')||'[]');}catch(error){return [];}};const localSave=(promos)=>localStorage.setItem('beadDifferentPromos',JSON.stringify(promos));let promos=cloud?(await window.beadSupabase.from('promo_codes').select('id,code,discount_type,value,mode,active').order('created_at',{ascending:false})).data||[]:read();const saveCloud=async(promo)=>{await window.beadSupabase.from('promo_codes').upsert(promo,{onConflict:'id'});};const draw=()=>{panel.innerHTML=`<div class="admin-heading"><div><p class="kicker">MARKETING</p><h2>Promo codes</h2><p>Create automatic promotions or codes customers must enter at checkout.</p></div></div><form class="admin-form promo-form"><div class="admin-form-grid"><label>Code<input name="code" required placeholder="WELCOME10"></label><label>Discount type<select name="type"><option value="percent">Percent</option><option value="fixed">Fixed amount</option></select></label></div><div class="admin-form-grid"><label>Value<input name="value" type="number" min="0" step="0.01" required></label><label>Mode<select name="mode"><option value="manual">Customer enters code</option><option value="auto">Apply automatically</option></select></label></div><button class="cta">Add promo</button></form><div class="admin-list promo-list">${promos.map((promo,index)=>`<article><div><strong>${adminSafe(promo.code||'Automatic promotion')} · ${promo.discount_type==='percent'||promo.type==='percent'?`${promo.value}% off`:`$${Number(promo.value).toFixed(2)} off`}</strong><span>${promo.mode==='auto'?'Automatic':'Code required'} · ${promo.active===false?'Inactive':'Active'}</span></div><div><button data-toggle-promo="${index}">${promo.active===false?'Activate':'Deactivate'}</button><button data-delete-promo="${index}">Delete</button></div></article>`).join('')||'<div class="admin-empty">No promo codes yet.</div>'}</div>`;panel.querySelector('form').addEventListener('submit',async(event)=>{event.preventDefault();const fields=Object.fromEntries(new FormData(event.currentTarget));const promo=cloud?{code:fields.code.toUpperCase(),discount_type:fields.type,value:Number(fields.value),mode:fields.mode,active:true}:{...fields,value:Number(fields.value),active:true};if(cloud){await saveCloud(promo);promos=(await window.beadSupabase.from('promo_codes').select('id,code,discount_type,value,mode,active').order('created_at',{ascending:false})).data||[];}else{promos.push(promo);localSave(promos);}draw();});panel.querySelectorAll('[data-toggle-promo]').forEach((button)=>button.addEventListener('click',async()=>{const promo=promos[Number(button.dataset.togglePromo)];promo.active=promo.active===false;if(cloud)await saveCloud({id:promo.id,active:promo.active});else localSave(promos);draw();}));panel.querySelectorAll('[data-delete-promo]').forEach((button)=>button.addEventListener('click',async()=>{const promo=promos[Number(button.dataset.deletePromo)];if(cloud)await window.beadSupabase.from('promo_codes').delete().eq('id',promo.id);else{promos.splice(Number(button.dataset.deletePromo),1);localSave(promos);}draw();}));};draw();}
