const baseAdminCatalog=adminCatalog;adminCatalog=()=>{const data=adminData();const base=baseAdminCatalog();const custom=Object.entries(data.products).filter(([id])=>!catalog.some((item)=>item.id===id)&&!data.deletedProducts.includes(id)).map(([id,product])=>({id,name:product.name||id,price:Number(product.price)||0,quantity:Number(product.quantity)||0,description:product.description||'',category:product.category||'uncategorized',image:(product.photos||'').split(/\s*[,\n]\s*/)[0]||'product-mix.jpg'}));return [...base,...custom];};
async function requireAdmin(){if(!window.beadSupabase){await loadAdminCloudData();renderTab();return;}const {data:{user}}=await window.beadSupabase.auth.getUser();if(!user){panel.innerHTML='<div class="product-unavailable"><h1>Admin sign-in required</h1><p>Sign in with the administrator account to access store controls.</p><a class="cta" href="account.html">Go to account</a></div>';return;}const {data:profile,error}=await window.beadSupabase.from('profiles').select('role,status').eq('id',user.id).maybeSingle();if(error||profile?.role!=='admin'||profile.status!=='active'){panel.innerHTML='<div class="product-unavailable"><h1>Admin access required</h1><p>This account is not authorized for store controls.</p></div>';return;}await loadAdminCloudData();const params=new URLSearchParams(location.search);if(params.get('edit')||params.get('new')==='item'){history.replaceState(null,'',location.pathname);return cloudItemForm(params.get('edit')||null).catch(renderCloudError);}renderTab();}
async function loadAdminCloudData(){if(!window.beadSupabase)return;const {data:categories}=await window.beadSupabase.from('categories').select('slug,name,cover_photo').order('sort_order');if(categories?.length){const data=adminData();data.categories=categories.map((category)=>({slug:category.slug,name:category.name,photo:category.cover_photo||''}));localStorage.setItem(adminDataKey,JSON.stringify(data));}const {data:settings}=await window.beadSupabase.from('site_settings').select('value').eq('key','store').maybeSingle();if(settings?.value){const config=window.productStoreConfig||{};Object.assign(config,settings.value.config||{});window.productStoreConfig=config;const data=adminData();data.settings=settings.value.admin||{};localStorage.setItem(adminDataKey,JSON.stringify(data));}}
async function renderCampaigns(){const cloud=Boolean(window.beadSupabase);let campaigns=[];let recipientCounts={marketing_opted_in:0,waitlist_product:0};if(cloud){const result=await window.beadSupabase.from('email_campaigns').select('id,subject,body,audience,status,created_at').order('created_at',{ascending:false});if(result.error){panel.innerHTML='<div class="admin-empty">Unable to load email drafts.</div>';return;}campaigns=result.data||[];const [subscriberResult,waitlistResult]=await Promise.all([window.beadSupabase.from('notification_subscribers').select('email').eq('active',true),window.beadSupabase.from('waitlist_entries').select('profiles(email)').neq('status','fulfilled')]);recipientCounts.marketing_opted_in=new Set((subscriberResult.data||[]).map((row)=>String(row.email).toLowerCase())).size;recipientCounts.waitlist_product=new Set((waitlistResult.data||[]).map((row)=>row.profiles?.email).filter(Boolean).map((email)=>String(email).toLowerCase())).size;}const draw=()=>{panel.innerHTML=`<div class="admin-heading"><div><p class="kicker">CUSTOMER COMMUNICATION</p><h2>Email drafts</h2><p>Create announcements for opted-in subscribers or waitlisted customers. Resend delivery will be connected later.</p></div></div><form class="admin-form"><label>Subject<input name="subject" required></label><label>Audience<select name="audience"><option value="marketing_opted_in">Newsletter subscribers (${recipientCounts.marketing_opted_in})</option><option value="waitlist_product">Waitlisted customers (${recipientCounts.waitlist_product})</option></select><small data-campaign-recipient-count>Recipients: ${recipientCounts.marketing_opted_in}</small></label><label>Message<textarea name="body" rows="7" required></textarea></label><button class="cta">Save draft</button></form><div class="admin-list">${campaigns.map((campaign)=>`<article><div><strong>${adminSafe(campaign.subject)}</strong><span>${adminSafe(campaign.audience)} · ${adminSafe(campaign.status)} · ${new Date(campaign.created_at).toLocaleDateString()}</span></div><button type="button" data-delete-campaign="${campaign.id}">Delete</button></article>`).join('')||'<div class="admin-empty">No email drafts yet.</div>'}</div>`;panel.querySelector('form [name="audience"]').addEventListener('change',(event)=>{panel.querySelector('[data-campaign-recipient-count]').textContent=`Recipients: ${recipientCounts[event.currentTarget.value]||0}`;});panel.querySelector('form').addEventListener('submit',async(event)=>{event.preventDefault();const fields=Object.fromEntries(new FormData(event.currentTarget));if(cloud){const {data:{user}}=await window.beadSupabase.auth.getUser();const result=await window.beadSupabase.from('email_campaigns').insert({author_id:user.id,subject:fields.subject,body:fields.body,audience:fields.audience,status:'draft'}).select('id,subject,body,audience,status,created_at').single();if(!result.error)campaigns.unshift(result.data);}else{campaigns.unshift({...fields,id:`draft-${Date.now()}`,status:'draft',created_at:new Date().toISOString()});}draw();});panel.querySelectorAll('[data-delete-campaign]').forEach((button)=>button.addEventListener('click',async()=>{if(cloud)await window.beadSupabase.from('email_campaigns').delete().eq('id',button.dataset.deleteCampaign);campaigns=campaigns.filter((campaign)=>campaign.id!==button.dataset.deleteCampaign);draw();}));};draw();}
const renderSubscribers=async()=>{const cloud=Boolean(window.beadSupabase);let records=[];if(cloud){const [subscriberResult,profileResult,preferenceResult]=await Promise.all([window.beadSupabase.from('notification_subscribers').select('email,active,source,created_at').order('created_at',{ascending:false}),window.beadSupabase.from('profiles').select('id,email,full_name,created_at').order('created_at',{ascending:false}),window.beadSupabase.from('customer_preferences').select('user_id,marketing_opt_in')]);if(subscriberResult.error||profileResult.error||preferenceResult.error){panel.innerHTML='<div class="admin-empty">Unable to load newsletter subscribers.</div>';return;}const members=new Map((profileResult.data||[]).map((profile)=>[profile.id,profile]));const optedIn=new Set((preferenceResult.data||[]).filter((preference)=>preference.marketing_opt_in).map((preference)=>preference.user_id));const byEmail=new Map();(subscriberResult.data||[]).filter((subscriber)=>subscriber.active).forEach((subscriber)=>byEmail.set(String(subscriber.email).toLowerCase(),{email:subscriber.email,name:'',source:subscriber.source,created_at:subscriber.created_at}));optedIn.forEach((userId)=>{const profile=members.get(userId);if(profile?.email&&!byEmail.has(profile.email.toLowerCase()))byEmail.set(profile.email.toLowerCase(),{email:profile.email,name:profile.full_name||'',source:'member',created_at:profile.created_at});});records=[...byEmail.values()];}else{const localSubscribers=JSON.parse(localStorage.getItem('beadDifferentNotificationSubscribers')||'[]');records=localSubscribers.map((email)=>({email,source:'footer',name:'',created_at:null}));}const draw=()=>{const needle=(panel.querySelector('[data-subscriber-search]')?.value||'').trim().toLowerCase();const filtered=records.filter((record)=>[record.email,record.name,record.source].filter(Boolean).join(' ').toLowerCase().includes(needle));const pageCount=Math.max(1,Math.ceil(filtered.length/adminPageSize));subscriberPage=Math.min(subscriberPage,pageCount);const page=filtered.slice((subscriberPage-1)*adminPageSize,subscriberPage*adminPageSize);const tableRows=page.map((record)=>'<tr><td>'+adminSafe(record.email)+'</td><td>'+adminSafe(record.name||'—')+'</td><td>'+adminSafe(record.source||'—')+'</td><td>'+adminSafe(record.created_at?new Date(record.created_at).toLocaleDateString():'—')+'</td><td><a href="mailto:'+encodeURIComponent(record.email)+'">Email</a></td></tr>').join('')||'<tr><td colspan="5">No subscribers found.</td></tr>';panel.innerHTML='<div class="admin-heading"><div><p class="kicker">CUSTOMER COMMUNICATION</p><h2>Newsletter Subscribers</h2><p>Anonymous footer signups and members who opted in to product drops, restocks, and promotions.</p></div></div><div class="admin-form-grid"><label>Search subscribers<input type="search" data-subscriber-search placeholder="Email or name"></label></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Email</th><th>Name</th><th>Source</th><th>Joined</th><th></th></tr></thead><tbody>'+tableRows+'</tbody></table></div><div class="admin-pagination"><button type="button" data-subscriber-page="prev" '+(subscriberPage<=1?'disabled':'')+'>Previous</button><span>Page '+subscriberPage+' of '+pageCount+'</span><button type="button" data-subscriber-page="next" '+(subscriberPage>=pageCount?'disabled':'')+'>Next</button></div>';panel.querySelector('[data-subscriber-search]').addEventListener('input',()=>{subscriberPage=1;draw();});panel.querySelectorAll('[data-subscriber-page]').forEach((button)=>button.addEventListener('click',()=>{subscriberPage+=button.dataset.subscriberPage==='next'?1:-1;draw();}));};draw();};function renderTab(){const renderers={overview:renderOverview,categories:renderCategories,items:renderItems,waitlist:renderWaitlist,stats:renderStats,subscribers:renderSubscribers,reviews:renderReviews,members:()=>renderSimple('members','Members','Review customer accounts, notes, and account status.','No members yet.'),orders:()=>renderSimple('orders','Orders','Review order history and update shipping details.','No orders yet.'),settings:renderSettings,campaigns:renderCampaigns,inventory:renderInventoryTools};Promise.resolve(renderers[activeTab]?.()).catch((error)=>{panel.innerHTML=`<div class="admin-empty">${adminSafe(error.message||'Unable to load this section.')}</div>`;});}
const campaignsTab=document.createElement('button');campaignsTab.className='admin-tab';campaignsTab.dataset.adminTab='campaigns';campaignsTab.textContent='Email drafts';document.querySelector('.admin-sidebar nav').append(campaignsTab);campaignsTab.addEventListener('click',()=>switchTab('campaigns'));const subscribersTab=document.createElement('button');subscribersTab.className='admin-tab';subscribersTab.dataset.adminTab='subscribers';subscribersTab.textContent='Newsletter Subscribers';document.querySelector('.admin-sidebar nav').append(subscribersTab);subscribersTab.addEventListener('click',()=>switchTab('subscribers'));
